        // 目标 1 件：BASIC 先卸，再卸 STANDARD，PREMIUM 始终最后保留
        offload("OFF-2", "LEG1", 2, 1, 1000).andExpect(status().isOk())
                .andExpect(jsonPath("$.offloaded[0].bagTag").value("BASIC_HEAVY"))
