        // 再装 BAG2：件数 3>2、总重 40>30，双维度超限整批 422，无一件移动
        postJson("/api/legs/LEG1/load", Map.of(
                "requestId", UUID.randomUUID().toString(),
                "expectedVersion", 2, "bagTags", List.of("BAG2")))
